// scripts/data/referenceCardDrafts.js
//
// New formula cards for the topics with the most questions and no cards (2026-11).
// Written by hand to the same standard as the rewrites. They go in as PENDING, so
// each one waits in Admin › Formula cards › Review until it's accepted. Constants
// are the CODATA 2018 values, checked in tests/referenceCardContent.test.js.
const m = String.raw;
const v = (symbol, meaning, unit = null) => ({ symbol, meaning, unit });
const U = {
  V: m`$\text{V}$`, A: m`$\text{A}$`, ohm: m`$\Omega$`, W: m`$\text{W}$`, J: m`$\text{J}$`, N: m`$\text{N}$`, m: m`$\text{m}$`, m2: m`$\text{m}^2$`, m3: m`$\text{m}^3$`,
  s: m`$\text{s}$`, kg: m`$\text{kg}$`, H: m`$\text{H}$`, F: m`$\text{F}$`, C: m`$\text{C}$`, Hz: m`$\text{Hz}$`, T: m`$\text{T}$`, Wb: m`$\text{Wb}$`, K: m`$\text{K}$`, Pa: m`$\text{Pa}$`,
  rpm: m`$\text{rpm}$`, ms: m`$\text{m/s}$`, ms2: m`$\text{m/s}^2$`, rads: m`$\text{rad/s}$`, Nm: m`$\text{N}\cdot\text{m}$`, lm: m`$\text{lm}$`, lx: m`$\text{lx}$`, cd: m`$\text{cd}$`, kVA: m`$\text{kVA}$`, MVA: m`$\text{MVA}$`, kV: m`$\text{kV}$`, deg: m`$^\circ$`, rad: m`$\text{rad}$`, mol: m`$\text{mol}$`, cfs: m`$\text{m}^3\text{/s}$`,
};

const formula = (subject, topic, tag, name, symbol, f, unit, vars, d, tip, dim = false) => ({ kind: 'formula', subject, topic, tag, name, symbol, f, unit, vars, d, tip, dim });
const constant = (subject, topic, tag, name, symbol, value, d, tip) => ({ kind: 'constant', subject, topic, tag, name, symbol, value, d, tip, vars: [] });

const ee = (topic) => (tag, ...rest) => formula('EE', topic, tag, ...rest);
const esas = (topic) => (tag, ...rest) => formula('ESAS', topic, tag, ...rest);
const math = (topic) => (tag, ...rest) => formula('Mathematics', topic, tag, ...rest);

const EM = ee('Electromagnetism');
const M1 = ee('Electrical Machinery 1');
const M2 = ee('Electrical Machinery 2');
const TR = ee('Electrical Transient Analysis');
const PS = ee('Power System Analysis');
const IL = ee('Electrical System & Illumination Design');
const EL = ee('Electronics 1 and 2');
const MECH = esas('Engineering Mechanics');
const FL = esas('Fluid Mechanics');
const DB = esas('Fundamentals of Deformable Bodies');
const PH = esas('Physics for Engineers');
const CH = esas('Chemistry for Engineers');
const TG = math('Trigonometry');
const SG = math('Solid Geometry');
const DE = math('Differential Equations');
const PB = math('Probability & Statistics');
const NM = math('Numerical Methods & Analysis');
const VA = math('Vector Analysis');

